  if (interaction.commandName === 'ban') {
    if (!interaction.member.permissions.has('BAN_MEMBERS')) {
      return interaction.reply({ content: 'You do not have permission to use this command.', ephemeral: true });
    }

    const user = interaction.options.getUser('user');
    const days = interaction.options.getInteger('days');

    if (days < 0 || days > 7) {
      return interaction.reply({ content: 'The number of days must be between 0 and 7.', ephemeral: true });
    }

    try {
      await interaction.guild.members.ban(user, { days: days });
      await interaction.reply({ content: `User ${user.tag} has been banned for ${days} days.`, ephemeral: true });
