// Function to count the occurrences of a word in a file
int countWordOccurrences(const std::string& filename, const std::string& word) {
    int count = 0;

    // Open the file for reading
    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Error opening file: " << filename << std::endl;
        return -1;
    }

    // Read the file line by line
    std::string line;
    while (std::getline(file, line)) {
        std::istringstream iss(line);
        std::string wordInLine;

        // Extract words from the line
        while (iss >> wordInLine) {
            // Convert both the word and the word in line to lowercase for case-insensitive comparison
            std::transform(wordInLine.begin(), wordInLine.end(), wordInLine.begin(), ::tolower);
            std::transform(word.begin(), word.end(), word.begin(), ::tolower);

            // Check if the word matches the word in the line
            if (wordInLine == word) {
                count++;
            }
        }
    }

    file.close();
    return count;
}

int main() {
    std::string filename, word;

    // Get the file name and word from the user
    std::cout << "Enter the file name: ";
    std::cin >> filename;
    std::cout << "Enter the word to count: ";
    std::cin >> word;

    // Count the occurrences of the word in the file
    int occurrences = countWordOccurrences(filename, word);

    // Display the result
    if (occurrences != -1) {
        std::cout << "The word '" << word << "' appears " << occurrences << " times in the file." << std::endl;
    }

    return 0;
}
